import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.Dd0PfFUD.js";const u=JSON.parse('{"title":"Agent identity","description":"","frontmatter":{},"headers":[],"relativePath":"security/walkthrough-agent-identity.md","filePath":"security/walkthrough-agent-identity.md"}'),o={name:"security/walkthrough-agent-identity.md"};function n(r,e,c,d,h,l){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="agent-identity" tabindex="-1">Agent identity <a class="header-anchor" href="#agent-identity" aria-label="Permalink to &quot;Agent identity&quot;">​</a></h1><p>The agent identity plane authenticates the agent making each hop. KAOS selects one actor-token issuer through <code>security.agentAuth.identity.provider</code>: <code>serviceaccount</code>, <code>oidc</code>, or <code>aib</code>. Every issuer must mint a JWT for the <code>kaos-gateway</code> audience.</p><h2 id="serviceaccount-issuer" tabindex="-1">ServiceAccount issuer <a class="header-anchor" href="#serviceaccount-issuer" aria-label="Permalink to &quot;ServiceAccount issuer&quot;">​</a></h2><p><code>serviceaccount</code> is the zero-dependency default. The operator creates an owned Kubernetes ServiceAccount for each Agent and mounts a projected token at <code>/var/run/secrets/kaos-agent/token</code>. <code>AGENT_AUTH_TOKEN_FILE</code> points the runtime to that path.</p><p>Kubelet mints and rotates the short-lived projected token. The runtime reads the file whenever it needs the actor token, so it sees rotated tokens without restarting. The token subject has the form <code>system:serviceaccount:&lt;namespace&gt;:&lt;serviceaccount-name&gt;</code>.</p><p>At startup, the operator discovers the Kubernetes issuer and JWKS from the API server. Gateway <code>SecurityPolicy</code> resources use <code>localJWKS</code> with those inline keys and require the <code>kaos-gateway</code> audience.</p><h2 id="aib-issuer" tabindex="-1">AIB issuer <a class="header-anchor" href="#aib-issuer" aria-label="Permalink to &quot;AIB issuer&quot;">​</a></h2><p><code>aib</code> uses the Agentic Identity Broker as the actor-token issuer. The operator registers each Agent with AIB and writes its client id and client secret to a per-agent Secret. Agent pods receive the provider-neutral <code>AGENT_AUTH_CLIENT_ID</code>, <code>AGENT_AUTH_CLIENT_SECRET_FILE</code>, and <code>AGENT_AUTH_TOKEN_ENDPOINT</code> settings.</p><p>The runtime uses OAuth <code>client_credentials</code> to obtain a short-lived actor token. It caches the token until refresh is needed, rereads the mounted client-secret file so Secret rotation is visible, and refreshes and retries once after a gateway 401. AIB owns credential and token issuance; it does not make resource authorization decisions.</p><p>The configured AIB issuer is the token <code>iss</code> value used by all verifiers. Gateway <code>SecurityPolicy</code> resources use <code>remoteJWKS</code> at the broker JWKS endpoint and require the <code>kaos-gateway</code> audience.</p><h2 id="oidc-issuer" tabindex="-1">OIDC issuer <a class="header-anchor" href="#oidc-issuer" aria-label="Permalink to &quot;OIDC issuer&quot;">​</a></h2><p><code>oidc</code> provides agent OAuth identity through RFC 7591/7592 Dynamic Client Registration (DCR). Select it with <code>--agent-auth-enabled keycloak</code>; add <code>--user-auth-enabled keycloak</code> when Keycloak should also provide user identity.</p><p>The operator registers one confidential OAuth client per Agent, stores the returned client id, client secret, and registration metadata in a per-agent Secret, and delivers the provider-neutral token endpoint and credential settings to the Agent pod. The runtime uses <code>client_credentials</code> to obtain short-lived actor tokens for the <code>kaos-gateway</code> audience. An Agent finalizer keeps the owned credential Secret available during deletion; the operator sends the RFC 7592 client deletion first, removes the Secret second, and only then releases the Agent for garbage collection.</p><p>DCR needs one manual bootstrap step: create an initial access token in Keycloak and place it in the configured Secret before the operator starts. The CLI prints the exact command during installation, for example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kaos-oidc-registration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kaos-system</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-literal=token=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The Secret name and key come from <code>security.agentAuth.identity.oidc.registration.initialAccessTokenSecretRef</code>. The operator pod remains pending until the Secret exists; the bootstrap credential is not created by KAOS.</p><h2 id="actor-identity-data" tabindex="-1">Actor identity data <a class="header-anchor" href="#actor-identity-data" aria-label="Permalink to &quot;Actor identity data&quot;">​</a></h2><p>The operator publishes issuer data in the policy ConfigMap:</p><ul><li><code>data.kaos.jwks</code> maps the exact actor-token issuer to its JWKS. The PDP selects this entry from <code>iss</code> and verifies the signature, exact issuer, <code>RS256</code> algorithm, and <code>kaos-gateway</code> audience.</li><li><code>data.kaos.agents</code> maps a logical actor id such as <code>kaos://agent/demo/researcher</code> to its issuer-specific identity and <code>autonomous</code> status. ServiceAccount tokens use <code>issuer_sub</code>. Keycloak client-credentials tokens carry the DCR <code>client_id</code> in <code>azp</code> and a separate service-account UUID in <code>sub</code>, so OIDC mappings use <code>issuer_azp</code>. This resolves a verified token to the KAOS actor used by authorization and controls whether the Agent may self-subject.</li></ul><p>ServiceAccount subjects require this mapping because their Kubernetes subject is not a KAOS resource id. Issuers that use the logical actor id directly as <code>sub</code> can be resolved without a mapping when no agent map is present.</p><p>The agent sends its token on every protected hop:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">x-agent-authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;actor-jwt&gt;</span></span></code></pre></div><p>The runtime replaces the actor identity at each agent hop with the current agent&#39;s own token. The user subject, when present, is propagated independently.</p>`,23)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
